INSERT INTO "battle" ("id", "slug", "author_id", "title", "context", "category_id", "tags", "deadline", "created_at") VALUES
  ('seed_lb_1', 'lrtUU479', (SELECT id FROM "user" WHERE handle = 'slicewars_dee'), 'Pineapple on pizza: yes or absolutely not?', 'Ordering for a group of 8. One pizza only.', 'other', '{}'::jsonb, now() + interval '95 hours', now() - interval '241 minutes'),
  ('seed_lb_2', 'lTj8pSXm', (SELECT id FROM "user" WHERE handle = 'comfyfeet_ro'), 'Socks with sandals: allowed?', 'My boyfriend swears it''s in style now.', 'other', '{}'::jsonb, now() + interval '92 hours', now() - interval '77 minutes'),
  ('seed_lb_3', 'lK7oYtbC', (SELECT id FROM "user" WHERE handle = 'dipdip_hooray'), 'What do you dip your fries in?', 'Settling a family argument at dinner.', 'other', '{}'::jsonb, now() + interval '92 hours', now() - interval '19 minutes'),
  ('seed_lb_4', 'ls6jf834', (SELECT id FROM "user" WHERE handle = 'tidyornot_kim'), 'Make the bed every morning?', 'Roommate says it''s a waste of time.', 'other', '{}'::jsonb, now() + interval '100 hours', now() - interval '466 minutes'),
  ('seed_lb_5', 'lYCi39rx', (SELECT id FROM "user" WHERE handle = 'adopting_alex_r'), 'Adopting our first pet. Dog or cat?', 'Small apartment, we both work, love cuddles.', 'other', '{}'::jsonb, now() + interval '98 hours', now() - interval '503 minutes'),
  ('seed_lb_6', 'lZLMCTy9', (SELECT id FROM "user" WHERE handle = 'flyfrequent_j'), 'Window or aisle on a 5 hour flight?', 'Booking right now.', 'other', '{}'::jsonb, now() + interval '111 hours', now() - interval '326 minutes'),
  ('seed_lb_7', 'lShx5P4R', (SELECT id FROM "user" WHERE handle = 'sundaymornin'), 'Sunday morning: coffee or tea?', 'Trying to cut back on caffeine a little.', 'other', '{}'::jsonb, now() + interval '100 hours', now() - interval '464 minutes'),
  ('seed_lb_8', 'lLQYiDUX', (SELECT id FROM "user" WHERE handle = 'ptoplanner_v'), 'Long weekend: beach or mountains?', '4 days off, just me and my partner.', 'other', '{}'::jsonb, now() + interval '112 hours', now() - interval '553 minutes'),
  ('seed_lb_9', 'lmtnmJxr', (SELECT id FROM "user" WHERE handle = 'brunchclub_mia'), 'Brunch order: pancakes or waffles?', 'Same price, I can only finish one.', 'other', '{}'::jsonb, now() + interval '107 hours', now() - interval '475 minutes'),
  ('seed_lb_10', 'lrPsA9iM', (SELECT id FROM "user" WHERE handle = 'phoneshy_ben'), 'Someone wants to make plans. Call or text back?', 'It''s a friend I haven''t seen in a while.', 'other', '{}'::jsonb, now() + interval '115 hours', now() - interval '568 minutes'),
  ('seed_lb_11', 'lqMq9nVy', (SELECT id FROM "user" WHERE handle = 'kitchenduty_t'), 'Dishes after dinner: dishwasher or by hand?', 'Just two of us, small load every night.', 'other', '{}'::jsonb, now() + interval '92 hours', now() - interval '80 minutes'),
  ('seed_lb_12', 'lCSREzaX', (SELECT id FROM "user" WHERE handle = 'filmbuff_noor'), 'New movie Friday: theater or couch?', 'It''s the big release everyone''s talking about.', 'other', '{}'::jsonb, now() + interval '111 hours', now() - interval '49 minutes'),
  ('seed_lb_13', 'lpjG4V6D', (SELECT id FROM "user" WHERE handle = 'splitcheck_sam'), 'Paying at the farmers market?', 'Small local stands, mostly under $20.', 'other', '{}'::jsonb, now() + interval '100 hours', now() - interval '168 minutes'),
  ('seed_lb_14', 'lXBY8r9Z', (SELECT id FROM "user" WHERE handle = 'tiredtuesday'), 'Exhausted after work. Dinner tonight?', 'It''s 8pm and nobody is judging.', 'other', '{}'::jsonb, now() + interval '106 hours', now() - interval '212 minutes'),
  ('seed_lb_15', 'lW7RyJWT', (SELECT id FROM "user" WHERE handle = '5am_or_never'), 'Thinking of changing my routine. Which one?', 'I get my best work done when it''s quiet.', 'other', '{}'::jsonb, now() + interval '92 hours', now() - interval '248 minutes'),
  ('seed_lb_16', 'lXGo8QcN', (SELECT id FROM "user" WHERE handle = 'wrapitup_june'), 'Wrapping birthday gifts: paper or bag?', 'I have 4 presents to wrap tonight.', 'other', '{}'::jsonb, now() + interval '86 hours', now() - interval '372 minutes'),
  ('seed_lb_17', 'lNXMwmtn', (SELECT id FROM "user" WHERE handle = 'needledrop_leo'), 'How do you listen to music at home?', 'Thinking about buying a record player.', 'other', '{}'::jsonb, now() + interval '94 hours', now() - interval '573 minutes'),
  ('seed_lb_18', 'lhpkeCSP', (SELECT id FROM "user" WHERE handle = 'bookworm_ivy'), 'Where do you get your next book?', 'I read about one book a week.', 'other', '{}'::jsonb, now() + interval '118 hours', now() - interval '44 minutes'),
  ('seed_lb_19', 'lD5wSfJa', (SELECT id FROM "user" WHERE handle = 'newhome_carla'), 'Painting the living room. DIY or hire someone?', 'Quote was $900. I''ve never painted a room.', 'other', '{}'::jsonb, now() + interval '92 hours', now() - interval '323 minutes'),
  ('seed_lb_20', 'lhBusMPV', (SELECT id FROM "user" WHERE handle = 'greenthumb_ola'), 'Houseplants: one big statement plant or lots of small ones?', 'Decorating a bright living room.', 'other', '{}'::jsonb, now() + interval '88 hours', now() - interval '486 minutes')
